from collections import deque

def findShortestPath(matrix):
    if not matrix or not matrix[0]:
        return -1
    R, C = len(matrix), len(matrix[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque()
    visited = [[False] * C for _ in range(R)]

    for r in range(R):
        if matrix[r][0] == 1:
            queue.append((r, 0, 1))
            visited[r][0] = True

    while queue:
        r, c, dist = queue.popleft()
        if c == C - 1:
            return dist
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and matrix[nr][nc] == 1:
                is_safe = True
                for x, y in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = nr + x, nc + y
                    if 0 <= nx < R and 0 <= ny < C and matrix[nx][ny] == 0:
                        is_safe = False
                        break
                if is_safe:
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    return -1
